/**
 * Apply import rules to already-parsed rows.
 *
 * row.amount must be a safe integer number of cents, not a decimal string.
 * today must be a valid YYYY-MM-DD string.
 *
 * Deduplication is scoped to this batch: existing stored transactions are not
 * supplied to this function. The first occurrence of a duplicate is retained.
 *
 * Returns:
 *   { rows, imported, skipped, deduplicated }
 *
 * Future-dated rows produce warnings and count as skipped. Duplicates count
 * separately as deduplicated.
 */
export function importRows(rows, today) {
	function isValidDate(value) {
		if (
			typeof value !== "string" ||
			!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value) ||
			value.length !== 10
		) {
			return false;
		}

		const date = new Date(`${value}T00:00:00.000Z`);
		return (
			Number.isFinite(date.getTime()) &&
			date.toISOString().slice(0, 10) === value
		);
	}

	if (!Array.isArray(rows)) {
		throw new Error("ledger: import rows must be an array");
	}
	if (!isValidDate(today)) {
		throw new Error("ledger: today must be a valid YYYY-MM-DD date");
	}

	// Validate the entire batch before emitting warnings or preparing results.
	for (const [index, row] of rows.entries()) {
		const label = `ledger: import row ${index + 1}`;

		if (row === null || typeof row !== "object" || Array.isArray(row)) {
			throw new Error(`${label} must be an object`);
		}
		if (!isValidDate(row.date)) {
			throw new Error(`${label} has an invalid date; expected YYYY-MM-DD`);
		}
		if (typeof row.payee !== "string" || !row.payee.trim()) {
			throw new Error(`${label} must have a nonempty payee`);
		}
		if (!Number.isSafeInteger(row.amount)) {
			throw new Error(`${label} amount must be a safe integer number of cents`);
		}
		if (row.memo != null && typeof row.memo !== "string") {
			throw new Error(`${label} memo must be a string when supplied`);
		}
	}

	const importedRows = [];
	const seen = new Map();
	let skipped = 0;
	let deduplicated = 0;

	for (const [index, row] of rows.entries()) {
		if (row.date > today) {
			console.warn(
				`ledger: skipping future-dated import row ${index + 1}: ${row.date}`,
			);
			skipped++;
			continue;
		}

		let amounts = seen.get(row.date);
		if (!amounts) {
			amounts = new Map();
			seen.set(row.date, amounts);
		}

		let payees = amounts.get(row.amount);
		if (!payees) {
			payees = new Set();
			amounts.set(row.amount, payees);
		}

		if (payees.has(row.payee)) {
			deduplicated++;
			continue;
		}
		payees.add(row.payee);

		importedRows.push({
			...row,
			amount: row.amount === 0 ? 0 : row.amount,
			memo: row.memo == null || row.memo.trim() === "" ? row.payee : row.memo,
		});
	}

	return {
		rows: importedRows,
		imported: importedRows.length,
		skipped,
		deduplicated,
	};
}
